class Leaderboard {
    private java.util.Map<Integer, Integer> scores = new java.util.HashMap<>();
    private java.util.TreeMap<Integer, Integer> sorted = new java.util.TreeMap<>(java.util.Collections.reverseOrder());
    public Leaderboard() {}
    public void addScore(int playerId, int score) {
        if (scores.containsKey(playerId)) {
            int old = scores.get(playerId);
            sorted.merge(old, -1, Integer::sum); if (sorted.get(old) == 0) sorted.remove(old);
            score += old;
        }
        scores.put(playerId, score);
        sorted.merge(score, 1, Integer::sum);
    }
    public int top(int K) {
        int sum = 0, count = 0;
        for (var e : sorted.entrySet()) {
            int take = Math.min(e.getValue(), K - count);
            sum += e.getKey() * take; count += take;
            if (count == K) break;
        }
        return sum;
    }
    public void reset(int playerId) {
        int old = scores.remove(playerId);
        sorted.merge(old, -1, Integer::sum); if (sorted.get(old) == 0) sorted.remove(old);
    }
}

import java.util.*;

class Leaderboard {
    private Map<Integer, Integer> scores;
    public Leaderboard() {
        scores = new HashMap();
    }
    public void addScore(int playerId, int score) {
        scores.put(playerId, scores.getOrDefault(playerId, 0) + score);
    }
    public int top(int K) {
        List<Integer> vals = new ArrayList(scores.values());
        Collections.sort(vals, Collections.reverseOrder());
        int sum = 0;
        for (int i = 0; i < K && i < vals.size(); i++) {
            sum += vals.get(i).intValue();
        }
        return sum;
    }
    public void reset(int playerId) {
        scores.remove(playerId);
    }
}
